CREATE PROCEDURE [EcsMacchine_selectrow]
	@P_2 VarChar(15),
	@sync_scope_local_id Int,
	@sync_scope_restore_count Int
AS
BEGIN
SELECT [side].[CodMac], [base].[Keys], [base].[Modu], [base].[NomMac], [base].[Tipo], [base].[ValIn1], [base].[ValIn2], [base].[ValIn3], [base].[ValIn4], [base].[ValIn5], [base].[ValIn6], [base].[ValIn7], [base].[ValIn8], [base].[ValIn9], [base].[ValIn10], [base].[ValIn11], [base].[ValIn12], [base].[ValIn13], [base].[ValIn14], [base].[ValIn15], [base].[ValIn16], [base].[TipoIn1], [base].[TipoIn2], [base].[TipoIn3], [base].[TipoIn4], [base].[TipoIn5], [base].[TipoIn6], [base].[TipoIn7], [base].[TipoIn8], [base].[TipoIn9], [base].[TipoIn10], [base].[TipoIn11], [base].[TipoIn12], [base].[TipoIn13], [base].[TipoIn14], [base].[TipoIn15], [base].[TipoIn16], [base].[CntrLet1], [base].[CntrLet2], [base].[CntrLet3], [base].[CntrLet4], [base].[CntrLet5], [base].[CntrLet6], [base].[CntrLet7], [base].[CntrLet8], [base].[CntrLet9], [base].[CntrLet10], [base].[CntrLet11], [base].[CntrLet12], [base].[CntrLet13], [base].[CntrLet14], [base].[CntrLet15], [base].[CntrLet16], [base].[CntrVal1], [base].[CntrVal2], [base].[CntrVal3], [base].[CntrVal4], [base].[CntrVal5], [base].[CntrVal6], [base].[CntrVal7], [base].[CntrVal8], [base].[CntrVal9], [base].[CntrVal10], [base].[CntrVal11], [base].[CntrVal12], [base].[CntrVal13], [base].[CntrVal14], [base].[CntrVal15], [base].[CntrVal16], [base].[InCnt1], [base].[InCnt2], [base].[InCnt3], [base].[InCnt4], [base].[InCnt5], [base].[InCnt6], [base].[InCnt7], [base].[InCnt8], [base].[InCnt9], [base].[InCnt10], [base].[InCnt11], [base].[InCnt12], [base].[InCnt13], [base].[InCnt14], [base].[InCnt15], [base].[InCnt16], [base].[RapCnt1], [base].[RapCnt2], [base].[RapCnt3], [base].[RapCnt4], [base].[RapCnt5], [base].[RapCnt6], [base].[RapCnt7], [base].[RapCnt8], [base].[RapCnt9], [base].[RapCnt10], [base].[RapCnt11], [base].[RapCnt12], [base].[RapCnt13], [base].[RapCnt14], [base].[RapCnt15], [base].[RapCnt16], [base].[Propr], [base].[PerDiv], [base].[DataInst], [base].[DataDis], [base].[ValPar], [base].[NImp], [base].[F0], [base].[T0], [base].[N0], [base].[D0], [base].[ValPiatto], [base].[PzPiatto], [base].[device], [base].[IngressoCrediti], [base].[IngressoGettoni], [base].[IngressoTickets], [base].[device_status], [base].[lastseen], [base].[offlinecount], [base].[onlinecount], [base].[cards_presentate], [base].[val_platinum], [base].[val_gold], [base].[val_silver], [base].[val_normal], [base].[is_happyhour], [base].[is_timeplay], [base].[is_online], [side].[sync_row_is_tombstone], [side].[local_update_peer_timestamp] as sync_row_timestamp, case when ([side].[update_scope_local_id] is null or [side].[update_scope_local_id] <> @sync_scope_local_id) then COALESCE([side].[restore_timestamp], [side].[local_update_peer_timestamp]) else [side].[scope_update_peer_timestamp] end as sync_update_peer_timestamp, case when ([side].[update_scope_local_id] is null or [side].[update_scope_local_id] <> @sync_scope_local_id) then case when ([side].[local_update_peer_key] > @sync_scope_restore_count) then @sync_scope_restore_count else [side].[local_update_peer_key] end else [side].[scope_update_peer_key] end as sync_update_peer_key, case when ([side].[create_scope_local_id] is null or [side].[create_scope_local_id] <> @sync_scope_local_id) then [side].[local_create_peer_timestamp] else [side].[scope_create_peer_timestamp] end as sync_create_peer_timestamp, case when ([side].[create_scope_local_id] is null or [side].[create_scope_local_id] <> @sync_scope_local_id) then case when ([side].[local_create_peer_key] > @sync_scope_restore_count) then @sync_scope_restore_count else [side].[local_create_peer_key] end else [side].[scope_create_peer_key] end as sync_create_peer_key from [EcsMacchine] [base] right join [EcsMacchine_tracking] [side] on [base].[CodMac] = [side].[CodMac] WHERE [side].[CodMac] = @P_2
END
